<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { useModuleRequests } from '../../Office/useModuleRequests';
import {failure,ApiError} from '../api';
const {all,request}=useModuleRequests();
import { useOffice } from '../../Office/context';
import { useAdmin } from '../context';
import { getSession } from '../../FleetAndDocuments/api';
import { registrationDate } from '../../FleetAndDocuments/presentation';
import SearchSelect from '../../Workshop/components/SearchSelect.vue';
import { pendingPurchase as legacyPending, rememberPurchase as legacyRemember, clearPurchase as legacyClear } from '../purchasingRecovery';
import type { PurchasingIntent } from '../purchasingRecovery';
interface Part {id:string;code:string;description:string;unit:string}
interface Supplier {id:string;name:string}
interface Need {id:string;description:string;quantity:string;spare_part_id?:string|null;is_effective:boolean;work_order_id:string}
interface PurchaseItem {id:string;spare_part_id:string;code:string;description:string;unit:string;quantity:string;workshop_material_need_id:string|null}
interface Decision {id:string;decision:'approved'|'rejected';reason:string;decided_by:{id:string|number;name:string};registered_at:string}
interface PurchaseRequest {id:string;supplier:Supplier;reason:string;requested_by:{id:string|number;name:string};registered_at:string;items:PurchaseItem[];decision:Decision|null}
interface Line {key:string;spare_part_id:string;quantity:string;workshop_material_need_id:string}
const officeHost=useOffice();
const recovery=officeHost?.recovery<PurchasingIntent>('administrative-purchasing');
const pendingPurchase=(actor:string)=>recovery?recovery.get(actor)??null:legacyPending(actor);
const rememberPurchase=(intent:PurchasingIntent)=>recovery?recovery.set(intent.actor,intent):legacyRemember(intent);
const clearPurchase=(actor:string)=>recovery?recovery.delete(actor):legacyClear(actor);
const ctx=useAdmin(), loading=ref(false), rows=ref<PurchaseRequest[]>([]), selected=ref<PurchaseRequest|null>(null);
const parts=ref<Part[]>([]), suppliers=ref<Supplier[]>([]), needs=ref<Need[]>([]), search=ref(''), page=ref(1), actor=ref('');
const form=ref(false), supplier=ref(''), reason=ref(''), decision=ref<'approved'|'rejected'>('approved'), deciding=ref(false), confirmed=ref('');
const lines=ref<Line[]>([]), pending=ref<PurchasingIntent|null>(null);
let generation=0;onBeforeUnmount(()=>generation++);
const partOptions=computed(()=>parts.value.map(p=>({value:p.id,label:`${p.code} · ${p.description} · ${p.unit}`})));
const supplierOptions=computed(()=>suppliers.value.map(p=>({value:p.id,label:p.name})));
const needOptions=computed(()=>needs.value.filter(n=>n.is_effective).map(n=>({value:n.id,label:`${n.description} · ${n.quantity} · Orden ${n.work_order_id}`})));
const filtered=computed(()=>rows.value.filter(r=>`${r.supplier.name} ${r.reason} ${r.items.map(i=>`${i.code} ${i.description}`).join(' ')}`.toLocaleLowerCase('es').includes(search.value.toLocaleLowerCase('es'))));
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/10))), visible=computed(()=>filtered.value.slice((page.value-1)*10,page.value*10));
async function load(propagate=false):Promise<void>{const run=++generation;loading.value=true;try{const session=officeHost?.context.value?.session??await getSession();if(!session.roles.includes('administrator'))throw new ApiError(403,'Acceso administrativo requerido.');const [records,p,s,n]=await Promise.all([all<PurchaseRequest>('/purchasing/requests'),all<Part>('/catalogs/spare-parts'),all<Supplier>('/catalogs/suppliers'),all<Need>('/workshop/material-needs?effective=1')]);if(run!==generation)return;actor.value=session.id;rows.value=records;parts.value=p;suppliers.value=s;needs.value=n;pending.value=pendingPurchase(session.id);if(pending.value)ctx.uncertain.value=true;if(selected.value)selected.value=records.find(r=>r.id===selected.value?.id) ?? null;}catch(error){if(propagate)throw error;if(run===generation)await ctx.report(error);}finally{if(run===generation)loading.value=false;}}
function addLine():void{lines.value.push({key:crypto.randomUUID(),spare_part_id:'',quantity:'',workshop_material_need_id:''});}
function create():void{if(pending.value)return;form.value=true;deciding.value=false;selected.value=null;supplier.value='';reason.value='';lines.value=[];addLine();ctx.errors.value={};}
async function consult(row:PurchaseRequest):Promise<void>{try{selected.value=await request<PurchaseRequest>(`/purchasing/requests/${row.id}`);form.value=false;deciding.value=false;}catch(error){await ctx.report(error);}}
function decide():void{if(!selected.value || pending.value)return;deciding.value=true;form.value=false;reason.value='';decision.value='approved';ctx.errors.value={};}
async function send(intent:PurchasingIntent,retry=false):Promise<void>{if(ctx.busy.value)return;confirmed.value='';if(retry)ctx.uncertain.value=false;let attempted=false;const ok=await ctx.mutate(intent.title,async()=>{attempted=true;const session=await getSession();if(session.id!==intent.actor || !session.roles.includes('administrator'))throw new ApiError(403,'La identidad o los permisos cambiaron.');rememberPurchase(intent);pending.value=intent;await request(intent.path,'POST',intent.body);clearPurchase(intent.actor);pending.value=null;form.value=false;deciding.value=false;confirmed.value='Solicitud o decisión confirmada. No representa compra ni recepción.';await load(true);});if(!ok && pending.value && !ctx.uncertain.value && (!retry||attempted)){clearPurchase(intent.actor);pending.value=null;}if(!ok && pending.value)ctx.uncertain.value=true;}
async function submit():Promise<void>{if(pending.value)return;const body={supplier_id:supplier.value,reason:reason.value,items:lines.value.map(l=>({spare_part_id:l.spare_part_id,quantity:l.quantity,...(l.workshop_material_need_id?{workshop_material_need_id:l.workshop_material_need_id}:{})})),request_key:crypto.randomUUID()};await send({actor:actor.value,path:'/purchasing/requests',body,title:'registrar solicitud de compra'});}
async function submitDecision():Promise<void>{if(!selected.value || pending.value)return;await send({actor:actor.value,path:`/purchasing/requests/${selected.value.id}/decisions`,body:{decision:decision.value,reason:reason.value,request_key:crypto.randomUUID()},title:'registrar decisión administrativa'});}
async function retry():Promise<void>{if(pending.value)await send(pending.value,true);}
onMounted(()=>load());
</script>
<template>
<section class="space-y-5">
<p class="notice-info">Una solicitud aprobada autoriza su contenido exacto. No confirma una compra ni aumenta existencias.</p>
<p v-if="confirmed" role="status" class="notice-success">{{confirmed}}</p>
<section v-if="pending" class="panel space-y-3"><h2 class="font-semibold">Operación pendiente de confirmación</h2><p>Se conserva el contenido y la clave originales. Consulta los registros o reenvía únicamente esta misma operación; no hay reintentos automáticos.</p><button class="btn-secondary" :disabled="ctx.busy.value||loading" @click="retry">Reintentar la misma operación</button></section>
<div class="flex flex-wrap gap-3"><button class="btn-primary" :disabled="loading||ctx.busy.value||ctx.uncertain.value||!!pending" @click="create">Registrar solicitud de compra</button><button class="btn-secondary" :disabled="loading||ctx.busy.value" @click="load()">Actualizar solicitudes</button><a class="btn-secondary" href="/administracion/catalogos" :aria-disabled="ctx.busy.value||!!pending" @click="(ctx.busy.value||pending)&&$event.preventDefault()">Gestionar repuestos y proveedores</a></div>
<form v-if="form" aria-label="Solicitud de compra" class="panel space-y-4" @submit.prevent="submit">
<h2 class="text-lg font-semibold">Nueva solicitud de compra</h2><fieldset :disabled="loading||ctx.busy.value||ctx.uncertain.value||!!pending" class="space-y-4">
<SearchSelect v-model="supplier" label="Proveedor" :options="supplierOptions" required :errors="ctx.errors.value.supplier_id" />
<article v-for="(line,index) in lines" :key="line.key" class="rounded border border-blue-200 p-3 space-y-3"><SearchSelect v-model="line.spare_part_id" :label="`Repuesto ${index+1}`" :options="partOptions" required :errors="ctx.errors.value[`items.${index}.spare_part_id`]"/><label class="block">Cantidad {{index+1}}<input :aria-label="`Cantidad ${index+1}`" v-model="line.quantity" class="field" required inputmode="decimal" pattern="[0-9]+(\.[0-9]{1,6})?" placeholder="Cantidad exacta"></label><SearchSelect v-model="line.workshop_material_need_id" :label="`Necesidad de Taller ${index+1} (opcional)`" :options="needOptions" :errors="ctx.errors.value[`items.${index}.workshop_material_need_id`]"/><button v-if="lines.length>1" class="btn-secondary" type="button" @click="lines.splice(index,1)">Quitar línea {{index+1}}</button></article>
<button class="btn-secondary" type="button" @click="addLine">Añadir repuesto</button><label class="block">Motivo de compra<textarea aria-label="Motivo de compra" v-model="reason" class="field" required maxlength="5000"/></label><div class="flex gap-3"><button class="btn-primary">Guardar solicitud</button><button type="button" class="btn-secondary" @click="form=false">Cancelar</button></div>
</fieldset></form>
<form v-if="deciding && selected" aria-label="Decisión de compra" class="panel space-y-4" @submit.prevent="submitDecision"><h2 class="font-semibold">Revisar contenido de la solicitud</h2><p>{{selected.supplier.name}} · {{selected.reason}}</p><ul><li v-for="item in selected.items" :key="item.id">{{item.code}} · {{item.description}}: {{item.quantity}} {{item.unit}}</li></ul><fieldset :disabled="ctx.busy.value||ctx.uncertain.value||!!pending"><label>Decisión<select aria-label="Decisión" v-model="decision" class="field" required><option value="approved">Aprobar</option><option value="rejected">Rechazar</option></select></label><label>Motivo de la decisión<textarea aria-label="Motivo de la decisión" v-model="reason" class="field" required maxlength="5000"/></label><div class="flex gap-3 mt-3"><button class="btn-primary">Guardar decisión</button><button type="button" class="btn-secondary" @click="deciding=false">Cancelar</button></div></fieldset></form>
<section class="panel space-y-4"><h2 class="font-semibold">Solicitudes de compra</h2><label>Buscar solicitudes<input aria-label="Buscar solicitudes" v-model="search" class="field" type="search" @input="page=1"></label><p v-if="loading" role="status">Consultando solicitudes…</p><div v-else class="overflow-x-auto"><table class="data-table"><thead><tr><th>Proveedor</th><th>Motivo</th><th>Fecha</th><th>Decisión</th><th>Acciones</th></tr></thead><tbody><tr v-for="row in visible" :key="row.id"><td>{{row.supplier.name}}</td><td>{{row.reason}}</td><td>{{registrationDate(row.registered_at)}}</td><td>{{row.decision?.decision==='approved'?'Aprobada':row.decision?.decision==='rejected'?'Rechazada':'Pendiente'}}</td><td><button class="btn-secondary" :disabled="ctx.busy.value||!!pending" @click="consult(row)">Consultar solicitud</button></td></tr></tbody></table><p v-if="!filtered.length">Sin solicitudes para esta búsqueda.</p></div><div class="flex gap-3 items-center"><button class="btn-secondary" :disabled="page<=1||loading" @click="page--">Anterior</button><p>{{filtered.length}} solicitudes · Página {{page}} de {{pages}}</p><button class="btn-secondary" :disabled="page>=pages||loading" @click="page++">Siguiente</button></div></section>
<section v-if="selected && !deciding" class="panel space-y-4"><h2 class="font-semibold">Detalle de solicitud</h2><p>{{selected.id}} · {{selected.supplier.name}}</p><p>{{selected.reason}} · {{selected.requested_by.name}} · {{registrationDate(selected.registered_at)}}</p><ul><li v-for="item in selected.items" :key="item.id">{{item.code}} · {{item.description}} · {{item.quantity}} {{item.unit}} <span v-if="item.workshop_material_need_id">· Necesidad {{item.workshop_material_need_id}}</span></li></ul><button v-if="!selected.decision" class="btn-primary" :disabled="ctx.busy.value||ctx.uncertain.value||!!pending" @click="decide">Registrar decisión administrativa</button><template v-else><h3 class="font-semibold">Historial de decisión</h3><p>{{selected.decision.decision==='approved'?'Aprobada':'Rechazada'}} · {{selected.decision.reason}} · {{selected.decision.decided_by.name}} · {{registrationDate(selected.decision.registered_at)}}</p></template><p>El registro y la decisión permanecen inmutables. No se crean órdenes ni movimientos de stock por aprobar esta solicitud.</p></section>
</section>
</template>
